questionvariables.text:
/* 1. INITIALISATIONS PAR DÉFAUT */
num: x$ den: x$ ans_correct: 0$ txt_lim: "0"$ cas_txt: "1"$ deg_rule: ""$ explication: ""$ parite_txt: ""$ signe_inf_txt: ""$ err_sign_inf: 999$ err_plus_inf: 999$ err_0_inf: 999$ err_L_0: 999$ 
/* 2. GÉNÉRATION ALÉATOIRE */
r_type: rand(4)$ r_sub: rand(3)$ 
/* --- CAS 1 : Limite = 0 (Degré num < Degré den) --- */
if r_type = 1 and r_sub = 1 then num: x^2 + x - 1$ if r_type = 1 and r_sub = 2 then num: 3*x - 4$ if r_type = 1 and r_sub = 3 then num: -2*x + 1$ if r_type = 1 and r_sub = 1 then den: x^3 + 2$ if r_type = 1 and r_sub = 2 then den: x^2 - 5$ if r_type = 1 and r_sub = 3 then den: x^4 + x$ if r_type = 1 then ans_correct: 0$ if r_type = 1 then txt_lim: "0"$ 
/* --- CAS 2 : Limite = L réel (Degrés égaux) --- */
if r_type = 2 and r_sub = 1 then num: 2*x^2 - x$ if r_type = 2 and r_sub = 2 then num: -4*x^3 + 2$ if r_type = 2 and r_sub = 3 then num: 3*x^4 - x^2$ if r_type = 2 and r_sub = 1 then den: x^2 + 3$ if r_type = 2 and r_sub = 2 then den: 2*x^3 - x$ if r_type = 2 and r_sub = 3 then den: -x^4 + 5$ if r_type = 2 and r_sub = 1 then ans_correct: 2$ if r_type = 2 and r_sub = 2 then ans_correct: -2$ if r_type = 2 and r_sub = 3 then ans_correct: -3$ if r_type = 2 and r_sub = 1 then txt_lim: "2"$ if r_type = 2 and r_sub = 2 then txt_lim: "-2"$ if r_type = 2 and r_sub = 3 then txt_lim: "-3"$ 
/* --- CAS 3 : Limite = +inf --- */
if r_type = 3 and r_sub = 1 then num: x^4 - x$ if r_type = 3 and r_sub = 1 then den: x^2 + 1$ if r_type = 3 and r_sub = 2 then num: -x^3 + 2$ if r_type = 3 and r_sub = 2 then den: x^2 - 4$ if r_type = 3 and r_sub = 3 then num: 2*x^2 - 5$ if r_type = 3 and r_sub = 3 then den: -x + 2$ if r_type = 3 then ans_correct: inf$ if r_type = 3 then txt_lim: "+\infty"$ 
/* --- CAS 4 : Limite = -inf --- */
if r_type = 4 and r_sub = 1 then num: x^3 + x - 1$ if r_type = 4 and r_sub = 1 then den: x^2 - 2$ if r_type = 4 and r_sub = 2 then num: -x^4 + 2*x^2$ if r_type = 4 and r_sub = 2 then den: x^2 + 5$ if r_type = 4 and r_sub = 3 then num: 5*x^3 - 1$ if r_type = 4 and r_sub = 3 then den: -x^2 + 3$ if r_type = 4 then ans_correct: -inf$ if r_type = 4 then txt_lim: "-\infty"$ 
/* 3. CALCULS POUR LA CORRECTION */
func: num/den$ deg_num: hipow(num, x)$ deg_den: hipow(den, x)$ diff_deg: deg_num - deg_den$ coeff_num: ev(leadcoef(num), simp)$ coeff_den: ev(leadcoef(den), simp)$ rapport: ev(coeff_num/coeff_den, simp)$ 
if mod(diff_deg, 2) = 0 then parite_txt: "paire"$ if mod(diff_deg, 2) = 1 then parite_txt: "impaire"$ 
if rapport > 0 then signe_inf_txt: "positif"$ if rapport < 0 then signe_inf_txt: "négatif"$ 
if r_type = 1 then cas_txt: "1"$ if r_type = 1 then deg_rule: "Le degré du numérateur est STRICTEMENT INFÉRIEUR au degré du dénominateur."$ if r_type = 1 then explication: "D'après le cours, dans ce cas, la limite en -infini est égale à 0."$ 
if r_type = 2 then cas_txt: "2"$ if r_type = 2 then deg_rule: "Le degré du numérateur est ÉGAL au degré du dénominateur."$ if r_type = 2 then explication: "D'après le cours, la limite vaut le quotient des coefficients dominants."$ 
if r_type = 3 or r_type = 4 then cas_txt: "3"$ if r_type = 3 or r_type = 4 then deg_rule: "Le degré du numérateur est STRICTEMENT SUPÉRIEUR au degré du dénominateur."$ if r_type = 3 or r_type = 4 then explication: "La différence des degrés est paire ou impaire. En -infini, la règle des signes donne cette limite."$ 
/* 4. GÉNÉRATION DES ERREURS CLASSIQUES */
if ans_correct = inf then err_plus_inf: -inf$ if ans_correct = -inf then err_plus_inf: inf$ if ans_correct = 0 then err_plus_inf: 0$ if ans_correct#0 and ans_correct#inf and ans_correct#-inf then err_plus_inf: ans_correct$ 
if ans_correct = inf then err_sign_inf: -inf$ if ans_correct = -inf then err_sign_inf: inf$ 
if ans_correct = inf or ans_correct = -inf then err_0_inf: 0$ 
if ans_correct = 0 then err_L_0: ev(rapport, simp)$
